+    longitude === undefined ||
+    latitude === null ||
+    latitude === undefined
+  ) {
+    return '';
+  }
+
+  const lng = typeof longitude === 'number' ? longitude.toFixed(6) : longitude;
+  const lat = typeof latitude === 'number' ? latitude.toFixed(6) : latitude;
+
+  return `${lng}, ${lat}`;
