+            target="_blank"
+          >
+            {index === 0
+              ? dashboard.dashboard_title
+              : `, ${dashboard.dashboard_title}`}
+          </GenericLink>
+        ))}
+      </span>
+    </DashboardLinksWrapper>
+  );
+};
+
+export default DashboardLinksExternal;

