+  return {
+    yScaleConfig: config,
+    min: finalMin,
+    max: finalMax,
+  };
+}
+
+/**
+ * Transforms raw data into chart data points
+ */
+export function transformChartData(
+  data: Array<number | null>,
+): Array<{ x: number; y: number }> {
+  return data.map((num, idx) => ({ x: idx, y: num ?? 0 }));
+}

