+  }
+
+  addSchema(schema: Schema): void {
+    this.schemas.push(schema);
+  }
+}
+
+export class Disposable implements coreType.Disposable {
+  static from(
+    ...disposableLikes: {
+      dispose: () => any;
+    }[]
+  ): Disposable {
+    return new Disposable(() => {
+      disposableLikes.forEach(disposable => {
