+  const {
+    id = 'test-extension',
+    name = 'Test Extension',
+    description = 'A test extension',
+    version = '1.0.0',
+    dependencies = [],
+    remoteEntry = '',
+    exposedModules = [],
+    extensionDependencies = [],
+    commands = [],
+    menus = {},
+    views = {},
