+  await waitFor(() => {
+    expect(initializeCallCount).toBe(1);
+  });
+
+  // Verify initialization is still only called once
+  expect(initializeCallCount).toBe(1);
+
+  // Restore original method
+  manager.initializeExtensions = originalInitialize;
+});

