+
+test('renders name and slug fields', () => {
+  render(
+    <Form>
+      <BasicInfoSection {...defaultProps} />
+    </Form>,
+  );
+
+  expect(screen.getByTestId('dashboard-name-field')).toBeInTheDocument();
