+        className="matrixify-cell"
+        data-row={cell.row}
+        data-col={cell.col}
+        data-row-label={cell.rowLabel}
+        data-col-label={cell.colLabel}
+      >
+        {showLabel && <CellHeader title={cellLabel}>{cellLabel}</CellHeader>}
+        <ChartWrapper>
+          <StatefulChart
+            id={cell.id}
+            formData={cell.formData}
+            width="100%"
+            height="100%"
+            enableNoResults
+            noDataComponent={MatrixNoDataComponent}
+            showLoading
+            hooks={enhancedHooks}
+          />
+        </ChartWrapper>
+      </CellContainer>
+    );
+  },
