+    slice_id: undefined,
+    header_font_size: undefined,
+    subheader: undefined,
+    show_title: undefined,
+    header_title_text_align: undefined,
+    header_text: undefined,
+  };
+
+  // Apply overrides
+  Object.assign(cellFormData, overrides);
+
+  // Add filters for dimension-based axes
