+      ...additionalFilters,
+    ];
+  }
+
+  // Set metrics based on row/column configuration
+  const metrics = [];
+
+  if (rowConfig && rowIndex !== null && rowConfig.mode === 'metrics') {
+    const metric = rowConfig.metrics?.[rowIndex];
+    if (metric) {
+      metrics.push(metric);
+    }
+  }
