+  } as MatrixifyFormData;
+
+  expect(isMatrixifyEnabled(formData)).toBe(false);
+});
+
+test('isMatrixifyEnabled should return true for valid metrics mode configuration', () => {
+  const formData = {
+    viz_type: 'table',
